public static String convertDatesToWeekdays(String date) {
    String[] tokens = date.split(" ");
    int month = Integer.parseInt(tokens[0]);
    int day = Integer.parseInt(tokens[1]);
    int year = Integer.parseInt(tokens[2]);

    Calendar calendar = Calendar.getInstance();
    calendar.set(year, month - 1, day);

    String weekday = calendar.getDisplayName(Calendar.DAY_OF_WEEK, Calendar.LONG, Locale.US);
    return String.format("%s %d, %d is a %s", tokens[0], tokens[1], tokens[2], weekday);
}

