public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with n nodes and edges
    Graph graph = new Graph(n, edges);

    // Initialize a queue to store the nodes to visit
    Queue<Integer> queue = new LinkedList<>();

    // Initialize a boolean array to keep track of the visited nodes
    boolean[] visited = new boolean[n];

    // Initialize a variable to keep track of the minimum time
    int minTime = 0;

    // Start at node 0 and add it to the queue
    queue.add(0);
    visited[0] = true;

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node from the queue
        int current = queue.remove();

        // If the current node has an apple, add its neighbors to the queue and increment the minimum time
        if (hasApple[current]) {
            for (int neighbor : graph.getNeighbors(current)) {
                if (!visited[neighbor]) {
                    queue.add(neighbor);
                    visited[neighbor] = true;
                }
            }
            minTime++;
        }
    }

    // Return the minimum time
    return minTime;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    while (!s.isEmpty()) {
        int smallest = -1;
        for (int i = 0; i < s.length(); i++) {
            if (smallest == -1 || s.charAt(i) < s.charAt(smallest)) {
                smallest = i;
            }
        }
        result.append(s.charAt(smallest));
        s = s.substring(0, smallest) + s.substring(smallest + 1);

        int largest = -1;
        for (int i = s.length() - 1; i >= 0; i--) {
            if (largest == -1 || s.charAt(i) > s.charAt(largest)) {
                largest = i;
            }
        }
        result.append(s.charAt(largest));
        s = s.substring(0, largest) + s.substring(largest + 1);
    }
    return result.toString();
}

