public static boolean isBoomerang(int[][] points) {
    // Calculate the slope of the first two lines
    int slope1 = (points[1][1] - points[0][1]) / (points[1][0] - points[0][0]);
    int slope2 = (points[2][1] - points[1][1]) / (points[2][0] - points[1][0]);

    // Check if the slopes are equal
    if (slope1 == slope2) {
        return false;
    }

    // Calculate the slope of the third line
    int slope3 = (points[2][1] - points[0][1]) / (points[2][0] - points[0][0]);

    // Check if the slopes are equal
    if (slope3 == slope1 || slope3 == slope2) {
        return false;
    }

    return true;
}

public static int findNthUglyNumber(int n) {
    int[] dp = new int[n + 1];
    dp[1] = 1;
    int i2 = 1, i3 = 1, i5 = 1;
    for (int i = 2; i <= n; i++) {
        int min = Math.min(dp[i2] * 2, Math.min(dp[i3] * 3, dp[i5] * 5));
        if (min == dp[i2] * 2) i2++;
        if (min == dp[i3] * 3) i3++;
        if (min == dp[i5] * 5) i5++;
        dp[i] = min;
    }
    return dp[n];
}

